entries[305992] = { ["name"] = "Peerless Alchemist Stone", ["text"] = "3 sec cast\nReagents:\nZin'anthid (300), Anchor Weed (100), Expulsom (60)\nCreate a Peerless Alchemist Stone.\nProfession:\nBattle for Azeroth Alchemy (165)\nDiscovery:\nAwakened Alchemist Stone\n\nPeerless Alchemist Stone\nBinds when picked up\nUnique-EquippedTrinket\n+ 16 Versatility\n\nPrismatic Socket\n\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 42 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n50\nRequires Kul Tiran Alchemy\n(175)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
entries[305993] = { ["name"] = "Awakened Alchemist Stone", ["text"] = "3 sec cast\nReagents:\nZin'anthid (225), Anchor Weed (80), Expulsom (40)\nCreate an Awakened Alchemist Stone.\nProfession:\nBattle for Azeroth Alchemy (165)\nDiscovery:\nUnbound Alchemist Stone\n\nAwakened Alchemist Stone\nBinds when picked up\nUnique-EquippedTrinket\n+ 14 Versatility\n\nPrismatic Socket\n\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 36 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\n50\nRequires Kul Tiran Alchemy\n(170)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
entries[305994] = { ["name"] = "Unbound Alchemist Stone", ["text"] = "3 sec cast\nReagents:\nZin'anthid (175), Anchor Weed (60), Expulsom (30)\nCreate an Unbound Alchemist Stone.\nDrop:\nN'Zoth's Cultists\n\nUnbound Alchemist Stone\nBinds when picked up\nUnique-Equipped: Alchemist Stone (1)Trinket\n+ 12 Versatility\n\nPrismatic Socket\n\nEquip: When you heal or deal damage you have a chance to increase your Strength, Agility, or Intellect by 31 for 15 sec. Your highest stat is always chosen.\nEquip: Increases the effect that healing and mana potions have on the wearer by 40%. This effect does not stack.\nRequires Kul Tiran Alchemy\n(165)\n\"Can be used for transmutations in place of a Philosopher's Stone.\"" }
